import numpy as np

def lookup_gamma(nbrs, v, passes, keep):
    """ACORN-gamma: filter the stored list of M*gamma, keep the first `keep`"""
    lst = nbrs[v]                      # nearest first
    return lst[passes[lst]][:keep]     # checks: len(lst); distances: <= keep

def lookup_acorn1(nbrs, v, passes, keep):
    """ACORN-1: one-hop and two-hop neighbours, filter, keep the first `keep`"""
    out, seen = [], {v}
    for u in nbrs[v]:
        for w in [u, *nbrs[u]]:        # u itself, then u's own list
            if w in seen:
                continue
            seen.add(w)                # one predicate check
            if passes[w]:              # u may fail: its list is read anyway
                out.append(w)
                if len(out) == keep:
                    return out
    return out

import heapq

def search_level0(q, ep, ef, lookup, passes, X, stats):
    d0 = ((X[ep] - q) ** 2).sum(); stats["dist"] += 1
    C, T = [(d0, ep)], {ep}               # candidates, visited
    W = [(-d0, ep)] if passes[ep] else [] # results: passing nodes only
    while C:
        dc, c = heapq.heappop(C)
        if len(W) >= ef and dc > -W[0][0]:
            break                         # closest candidate is too far
        new = [w for w in lookup(c) if w not in T]
        if not new:
            continue
        d = ((X[new] - q) ** 2).sum(1); stats["dist"] += len(new)
        for w, dw in zip(new, d):
            T.add(w)
            if len(W) < ef or dw < -W[0][0]:
                heapq.heappush(C, (dw, w))
                if passes[w]:
                    heapq.heappush(W, (-dw, w))
                    if len(W) > ef:
                        heapq.heappop(W)
    return [w for _, w in sorted((-d, w) for d, w in W)][:10]

def nodes_to_score(nbrs, accept, filter_ratio, max_conn, graph):
    mult = round(min(1 / filter_ratio, max_conn / 2))
    to_score = [u for u in nbrs if accept(u)]
    to_explore = [u for u in nbrs if not accept(u)]
    filtered = len(to_explore) / len(nbrs)
    cap = mult if filtered == 1 else min(mult, 1 / (1 - filtered))
    max_to_score = int(len(nbrs) * cap)
    if len(to_score) < max_to_score and filtered > 0.10:
        for u in to_explore:                # second hop
            for w in graph[u]:
                if len(to_score) >= max_to_score:
                    break
                if accept(w):
                    to_score.append(w)
    return to_score                         # only these get distances
